// Colour maps and scales of the field maps (step M1.5, engine.md §9), as tables (no library). The tables are
// generated by scripts/harness/emsim/colormap-gen.mjs, which the harness reruns and compares byte for byte.
//
// - 'sequential' (|E|, |D|, |H|, φ ≥ 0): a straight line in OKLab from dark blue oklch(0.27 0.10 265°) to light yellow
//   oklch(0.93 0.14 100°): equal OKLab steps by construction (perceptually uniform), lightness rising monotonically
//   (it reads as a brightness ramp in grey and under every colour-vision deficiency), and the blue–yellow axis that
//   red–green colour-blind viewers keep, the idea of cividis. Neither end is black or white, so the map stays apart
//   from both the light and the dark page background (the dark end has the blue hue against the site's #2b2b2b).
// - 'diverging' (signed: Ex, Ez, a mode's φ): blue oklch(0.45 0.13 255°) → near white oklch(0.965 0 0) → red
//   oklch(0.45 0.15 30°), two straight lines in OKLab with the ends at the same lightness, so +x and −x are equally
//   strong and told apart by hue (blue and red stay apart for red–green colour-blind viewers, as in ColorBrewer's RdBu).

export type MapName = 'sequential' | 'diverging';
export type ScaleKind = 'linear' | 'log' | 'signed';

const HEX: Record<MapName, string> = {
  sequential: '',
  diverging: '',
};

const TABLES: Partial<Record<MapName, Uint8Array>> = {};

/** The 256 RGB entries of a map (3 bytes each). */
export function mapTable(name: MapName): Uint8Array {
  let t = TABLES[name];
  if (!t) {
    const h = HEX[name];
    t = new Uint8Array(h.length / 2);
    for (let i = 0; i < t.length; i++) t[i] = parseInt(h.substr(2 * i, 2), 16);
    TABLES[name] = t;
  }
  return t;
}

export interface Scale {
  kind: ScaleKind;
  map: MapName;
  lo: number; // linear: the value at the first entry; log: the lowest value shown (> 0); signed: −hi
  hi: number;
  ticks: number[]; // values for the scale bar's labels, inside [lo, hi]
}

// "Nice" tick values (1, 2, 5 × 10ⁿ) between lo and hi, about n of them.
export function niceTicks(lo: number, hi: number, n = 5): number[] {
  if (!(hi > lo)) return [lo];
  const raw = (hi - lo) / Math.max(1, n);
  const p = 10 ** Math.floor(Math.log10(raw));
  const m = raw / p;
  const step = (m < 1.5 ? 1 : m < 3.5 ? 2 : m < 7.5 ? 5 : 10) * p;
  const out: number[] = [];
  for (let v = Math.ceil(lo / step - 1e-9) * step; v <= hi + step * 1e-9; v += step) out.push(Math.abs(v) < step * 1e-9 ? 0 : v);
  return out;
}

function logTicks(lo: number, hi: number): number[] {
  const out: number[] = [];
  for (let e = Math.ceil(Math.log10(lo) - 1e-9); e <= Math.floor(Math.log10(hi) + 1e-9); e++) out.push(10 ** e);
  return out;
}

// Percentiles from at most 20 000 samples (stride), skipping NaN and the points the mask leaves out (cls < 0:
// copper).
function sample(values: ArrayLike<number>, cls: ArrayLike<number> | null, abs: boolean): Float64Array {
  const n = values.length;
  const stride = Math.max(1, Math.floor(n / 20000));
  const out: number[] = [];
  for (let i = 0; i < n; i += stride) {
    if (cls && cls[i] < 0) continue;
    const v = values[i];
    if (v === v) out.push(abs ? Math.abs(v) : v);
  }
  return Float64Array.from(out).sort();
}
const pick = (s: Float64Array, p: number) => (s.length ? s[Math.min(s.length - 1, Math.max(0, Math.round(p * (s.length - 1))))] : 0);

/**
 * A scale for a grid of values. clip (default 0.995): the top of the scale is that percentile, not the maximum (the
 * field is singular at copper corners, whose few points would otherwise darken the whole picture); decades (log): how
 * far below the top the scale reaches (default 3); cls: points with cls < 0 (copper) are left out.
 */
export function scaleOf(values: ArrayLike<number>, kind: ScaleKind, opt: { clip?: number; decades?: number; cls?: ArrayLike<number> | null } = {}): Scale {
  const clip = opt.clip ?? 0.995;
  const s = sample(values, opt.cls ?? null, kind !== 'linear');
  if (kind === 'signed') {
    const hi = pick(s, clip) || 1;
    return { kind, map: 'diverging', lo: -hi, hi, ticks: niceTicks(-hi, hi, 4) };
  }
  if (kind === 'log') {
    const hi = pick(s, clip) || 1;
    const lo = Math.max(pick(s, 1 - clip), hi * 10 ** -(opt.decades ?? 3));
    return { kind, map: 'sequential', lo, hi, ticks: logTicks(lo, hi) };
  }
  let lo = pick(s, 1 - clip);
  let hi = pick(s, clip);
  if (lo >= 0 && lo < 0.05 * hi) lo = 0; // a magnitude starts at zero
  if (!(hi > lo)) hi = lo + 1;
  return { kind, map: 'sequential', lo, hi, ticks: niceTicks(lo, hi) };
}

/** The table index (0 … 255) of a value on a scale; −1 for NaN. */
export function indexOf(scale: Scale, v: number): number {
  if (v !== v) return -1;
  let t: number;
  if (scale.kind === 'log') t = v > 0 ? Math.log(v / scale.lo) / Math.log(scale.hi / scale.lo) : 0;
  else t = (v - scale.lo) / (scale.hi - scale.lo);
  return t <= 0 ? 0 : t >= 1 ? 255 : Math.min(255, Math.floor(t * 256));
}

export interface RgbaOptions {
  cls?: ArrayLike<number> | null; // points with cls < 0 are copper
  copper?: [number, number, number, number]; // its colour (default: transparent, so the page draws the copper)
  out?: Uint8ClampedArray;
  flipY?: boolean; // default true: grid row 0 is the bottom (z0) of the view, ImageData row 0 the top
}

/**
 * A grid (nx × ny, row-major from the bottom row) as ImageData-ready RGBA bytes on a scale. NaN is transparent.
 */
export function toRGBA(values: ArrayLike<number>, nx: number, ny: number, scale: Scale, opt: RgbaOptions = {}): Uint8ClampedArray {
  const out = opt.out ?? new Uint8ClampedArray(nx * ny * 4);
  const tab = mapTable(scale.map);
  const cls = opt.cls ?? null;
  const cu = opt.copper ?? [0, 0, 0, 0];
  const flip = opt.flipY !== false;
  const log = scale.kind === 'log';
  const a = log ? Math.log(scale.lo) : scale.lo;
  const f = 256 / (log ? Math.log(scale.hi) - a : scale.hi - scale.lo);
  for (let j = 0; j < ny; j++) {
    const row = flip ? ny - 1 - j : j;
    for (let i = 0; i < nx; i++) {
      const k = j * nx + i;
      const o = (row * nx + i) * 4;
      if (cls && cls[k] < 0) { out[o] = cu[0]; out[o + 1] = cu[1]; out[o + 2] = cu[2]; out[o + 3] = cu[3]; continue; }
      const v = values[k];
      if (v !== v) { out[o + 3] = 0; continue; }
      let t = ((log ? (v > 0 ? Math.log(v) : -Infinity) : v) - a) * f;
      t = t < 0 ? 0 : t > 255 ? 255 : t;
      const e = (t | 0) * 3;
      out[o] = tab[e]; out[o + 1] = tab[e + 1]; out[o + 2] = tab[e + 2]; out[o + 3] = 255;
    }
  }
  return out;
}

/** The scale bar: a horizontal strip w × h of the map from lo (left) to hi (right), RGBA. */
export function scaleBar(scale: Scale, w: number, h: number): Uint8ClampedArray {
  const out = new Uint8ClampedArray(w * h * 4);
  const tab = mapTable(scale.map);
  for (let i = 0; i < w; i++) {
    const e = Math.min(255, Math.floor(((i + 0.5) / w) * 256)) * 3;
    for (let j = 0; j < h; j++) {
      const o = (j * w + i) * 4;
      out[o] = tab[e]; out[o + 1] = tab[e + 1]; out[o + 2] = tab[e + 2]; out[o + 3] = 255;
    }
  }
  return out;
}

/** Where a value sits on the scale bar, 0 (left) … 1 (right), for placing tick labels. */
export function barPosition(scale: Scale, v: number): number {
  const t = scale.kind === 'log' ? Math.log(v / scale.lo) / Math.log(scale.hi / scale.lo) : (v - scale.lo) / (scale.hi - scale.lo);
  return Math.min(1, Math.max(0, t));
}
